mapper.update:
UPDATE BUSINESS_TRIP
SET
    START_DATE = TO_DATE(#{startDate}, 'YYYY-MM-DD')
    , END_DATE = TO_DATE(#{endDate}, 'YYYY-MM-DD')
    , MEMO = #{memo}
WHERE NO = #{no}
AND MEMBER_NO = #{memberNo}
AND DEL_YN = 'N'

UPDATE BUSINESS_TRIP
SET
DEL_YN = 'Y'
WHERE NO = #{no}
AND MEMBER_NO = #{memberNo}

UPDATE OUTSIDE_WORK
SET
DEL_YN = 'Y'
WHERE NO = #{no}
AND MEMBER_NO = #{memberNo}

UPDATE MEMBER
SET
ANNUAL = ANNUAL - #{usedDays}
WHERE NO = #{memberNo}

UPDATE VACATION
SET
    START_DATE = TO_DATE(#{startDate}, 'YYYY-MM-DD')
    , END_DATE = TO_DATE(#{endDate}, 'YYYY-MM-DD')
    , USED_DAYS = #{usedDays}
    , HALF_DAY_TYPE = #{halfDayType}
WHERE NO = #{no}
AND MEMBER_NO = #{memberNo}
AND DEL_YN = 'N'

UPDATE VACATION
SET
    DEL_YN = 'Y'
WHERE NO = #{no}
AND MEMBER_NO = #{memberNo}
